var data, font, points, lc;
var DT_MIN = -2, DT_MAX = 2; // delta temp MIN/MAX
var DHpY = -10; // delta height (y) per Year; data from 1880..2024

function preload() {
	// data = loadTable('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png', 'csv', 'header');
	data = loadStrings("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/GLB_Ts_dSST.csv");
	// Playfair Display 500
	font = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png')
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	describe("reimplementation of animation of the climate spiral from 1880 till 2024")

	textFont(font)
	textAlignnoStroke();
	fill(212);

	points = getValues(data);
	// console.log(points)
}

function getValues(data) {
	const [INFO] = data.splice(0, 1); // remove first Info line
	const [HEADER] = data.splice(0, 1); // remove header
	// console.log(INFO, HEADER);

	points = [];
	let lastVal; // for dummy value "***" duplicate last valid value
	let yRow = 0;
	for (row of data) {
		// Year,Jan,Feb,Mar,Apr,May,Jun,Jul,Aug,Sep,Oct,Nov,Dec
		const fields = row.split(",");
		const year = fields[0];
		for (month = 1; month <= 12; month++) {
			let val = fields[month];
			if (val == "***") {
				val = lastVal;
			}
			// exit, when end of data
			if (year === 2024 && val == "***") return points;

			const t = parseFloat(val);
			if (isNaN(t)) return points;
			const f = (month - 1) / 12; // 0..11/12
    	const a = f * TWO_PI;
	    const r = width * 0.5 * map(t, DT_MIN, DT_MAX, 0.1, 2);

			let c;
			const cw = color("white");
			const c1 = color("blue");
			const c2 = color("red");
			if (t < 0) {
				c = lerpColor(c1, cw, t/DT_MIN);
			} else {
				c = lerpColor(cw, c2, t/DT_MAX);
			}

			const x = cos(a) * r;
			const y = yRow + DHpY * f;
			const z = sin(a) * r;

			// line(x1, y1, z1, x2, y2, z2);
			points.push({ x, y, z, t, c });

			lastVal = val;
		}
		yRow += DHpY;
	}

	return points;
}

function draw() {
	background(0, 0, 12);

	lights()
	directionalLight(50, 50, 50, 0, 1, -0.5)

	camera(0, -1500, 2500, 0, 0, -1000);
	orbitControl();

	push();
	rotateY(frameCount * -0.004)

	strokeWeight(5)
	noFill()
	beginShape()
	let cc;
	const frI = frameCount % (points.length * 1.1); // halt for a while before restarting
	const maxI = min(frI, points.length);
	curveDetail(4);
	for (i = 0; i < maxI; i++) {
		const p = points[i];
		cc = p.c;
		stroke(p.c)
		curveVertex(p.x, p.y, p.z); // sooooo slooooow -> thx Dave for the hint in the comments, much faster
		// vertex(p.x, p.y, p.z)
	}
	endShape();


	noStroke();
	if (!lc) lc = cc;
	lc = lerpColor(lc, cc, 0.02);
	fill(red(window.color(lc)), green(window.color(lc)), blue(window.color(lc)), 32);
	const maxWH = max(width, height);
	box(maxWH * 2, 1, maxWH * 2)

	pop();

	fill(0, 0, 12)
	fill("white")
	translate(0, -1500, 1000 + frI / 2)
	// msg = year
	let msg = 1880 + ~~(frI/12);
	if (msg > 2024) msg = "climate change is real"
	textSize(msg <= 2024 ? 120 : 80)
	text(msg, 0, 0)

}
